'use strict';
const $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>new Intl.NumberFormat('ro-RO',{maximumFractionDigits:2}).format(n),short=n=>{const i=n>=1e9?3:n>=1e6?2:n>=1e3?1:0;return fmt(n/1000**i)+['','k','kk','kkk'][i]};
const image=n=>`images/${encodeURIComponent(n==='Glimmer Dust'?n:n.replaceAll(' ','_'))}.webp`;
const pic=n=>`<img src="${image(n)}" alt="" loading="lazy">`,named=n=>`<span class="matname">${pic(n)}<span>${esc(n)}</span></span>`;
const categories=['Arme','Armuri','Coifuri','Scuturi','Cercei','Brățări','Coliere','Încălțăminte','Curele'];
const defaults=()=>({item:'Onyx Bracelet',enabled:{},fails:{},adjust:{},prices:{},gaya:{qty:1,stone:0,dust:0},metin:{dps:90000,minutes:150,travel:0,selected:['murder'],prices:{},seed:1234567}});
let state=defaults(),page='home',runs={},job=0;
function finite(n,max=1e12){return typeof n==='number'&&Number.isFinite(n)&&n>=0&&n<=max;}
function restore(raw){const s=defaults();if(!raw||typeof raw!=='object')return s;
 if(GAME.items.some(x=>x.n===raw.item))s.item=raw.item;
 for(const key of ['prices','fails','adjust','enabled']){const obj=raw[key];if(!obj||typeof obj!=='object'||Array.isArray(obj))continue;for(const [k,v]of Object.entries(obj)){if(['__proto__','constructor','prototype'].includes(k))continue;if(key==='enabled'){if(typeof v==='boolean')s[key][k]=v;}else if(key==='adjust'?typeof v==='number'&&Number.isFinite(v)&&Math.abs(v)<=1e12:finite(v))s[key][k]=v;}}
 for(const [k,min,max]of [['qty',1,9999],['stone',0,1e12],['dust',0,1e12]])if(finite(raw.gaya?.[k],max)&&raw.gaya[k]>=min)s.gaya[k]=k==='qty'?Math.floor(raw.gaya[k]):raw.gaya[k];
 for(const [k,min,max]of [['dps',1,9999999],['minutes',1,1440],['travel',0,600],['seed',0,4294967295]])if(finite(raw.metin?.[k],max)&&raw.metin[k]>=min)s.metin[k]=Math.floor(raw.metin[k]);
 if(Array.isArray(raw.metin?.selected)){const ids=[...new Set(raw.metin.selected)].filter(id=>GAME.metins.some(m=>m.id===id)).slice(0,2);if(ids.length)s.metin.selected=ids;}
 if(raw.metin?.prices&&typeof raw.metin.prices==='object')for(const [k,v]of Object.entries(raw.metin.prices))if(finite(v)&&!['__proto__','constructor','prototype'].includes(k))s.metin.prices[k]=v;
 return s;
}
try{state=restore(JSON.parse(localStorage.getItem('lirin-forge-v1')))}catch{}
function save(){try{localStorage.setItem('lirin-forge-v1',JSON.stringify(state))}catch{toast('Salvarea locală nu este disponibilă. Exportă setările pentru a le păstra.')}}
function toast(s){$('toast').textContent=s;$('toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').style.display='none',3500)}
const heading=(k,title,desc)=>`<div class="eyebrow">${k}</div><h1>${title}</h1><p class="lead">${desc}</p>`;
const input=(label,key,value,extra='')=>`<label class="field">${label}<input data-key="${key}" value="${value}" inputmode="decimal" ${extra}><span class="errorhint" hidden></span></label>`;
function current(){return GAME.items.find(x=>x.n===state.item)}
function itemMaps(key){return Object.fromEntries(Object.entries(state[key]).filter(([k])=>k.startsWith(state.item+'|')).map(([k,v])=>[k.slice(state.item.length+1),v]));}
function upgradeResult(){return Calc.upgrade(current(),itemMaps('enabled'),itemMaps('fails'),itemMaps('adjust'),state.prices)}
function home(){return `<div class="hero"><div><div class="eyebrow">PLANIFICĂ. COMPARĂ. EVOLUEAZĂ.</div><h1>Următorul nivel<br>începe cu un calcul.</h1><p>Un atelier pentru resursele tale. Află cât investești, ce poți obține și unde merită timpul tău.</p><button class="primary" data-go="upgrade">Planifică un upgrade ↗</button></div><div class="heroart"><div class="orbit">${pic('Onyx Crystal')}</div><small>PRECIZIE ÎNAINTE DE NOROC</small></div></div><div class="sectionline"><h2>Alege instrumentul</h2><span class="tag">3 aplicații · un singur atelier</span></div><div class="cards">${[['upgrade','01','Rune Sword','Cost upgrade','De la craft la +9. Materiale, încercări și costuri, într-un singur plan.','Deschide calculatorul'],['metin','02','Murder Rock','Simulator Metin','Compară două zone de farm și vezi ce aduce o sesiune de joc.','Simulează o sesiune'],['gaya','03','Gaya','Calculator Gaya','Rețeta completă, taxa NPC și bugetul pentru cantitatea dorită.','Calculează costul']].map(([id,n,img,t,d,b])=>`<a class="card" href="#${id}"><div class="art"><span class="number">${n}</span>${pic(img)}</div><h3>${t}</h3><p>${d}</p><div class="link">${b}<span>↗</span></div></a>`).join('')}</div><div class="notebox"><b>Atelierul păstrează progresul.</b> Prețurile și setările se salvează în browser. Poți introduce sume precum 250k, 1,5kk sau 2kkk. Denumirile obiectelor rămân cele din joc.<br>Special Upgrade, Sash Absorption și Coin Calculator erau marcate „Soon” în original; nu conțineau aplicații funcționale.</div><div class="sectionline"><h2>Setările tale</h2><label class="quiet">Importă un export JSON <input type="file" id="import" accept="application/json,.json"></label></div>`;}
function upgrade(){const it=current();return heading('01 / PLANIFICATOR','Fiecare upgrade, calculat.','Alege echipamentul, bifează etapele și introdu prețurile de pe serverul tău.')+`<div class="tabs" aria-label="Categorii">${categories.map((n,i)=>`<button data-cat="${i}" class="${it.c===i?'selected':''}" aria-pressed="${it.c===i}">${n}</button>`).join('')}</div><div class="toolbar"><label class="field">Echipament<select id="item">${GAME.items.filter(x=>x.c===it.c).map(x=>`<option ${x.n===it.n?'selected':''}>${esc(x.n)}</option>`).join('')}</select></label><button data-action="all">Selectează / golește etapele</button><button data-action="resetUpgrade" class="quiet">Resetează planul</button></div><div class="layout"><div class="stack"><section class="panel"><div class="itemheading">${pic(it.n)}<div><h2>${esc(it.n)}</h2><span class="help">${categories[it.c]} · ${it.steps.filter(Boolean).length} etape disponibile</span></div></div><div class="tablewrap"><table><thead><tr><th>ETAPĂ</th><th>REȚETĂ / ÎNCERCARE</th><th>TAXĂ NPC</th><th>EȘECURI</th></tr></thead><tbody>${it.steps.map((row,i)=>!row?'':`<tr class="${state.enabled[it.n+'|'+i]===false?'off':''}"><td><label><input type="checkbox" data-step="${i}" ${state.enabled[it.n+'|'+i]!==false?'checked':''}> ${i?'+'+i:'Craft'}</label></td><td class="recipe">${row.slice(1).reduce((a,x,j,arr)=>j%2?a:[...a,`${arr[j+1]} × ${esc(GAME.materials[x]||x)}`],[]).join('<br>')||'Fără materiale'}</td><td>${short(row[0])}</td><td>${i?`<input class="fail" type="number" min="0" max="${it.fails?.[i]||99}" data-fail="${i}" value="${Math.min(state.fails[it.n+'|'+i]||0,it.fails?.[i]||99)}" aria-label="Eșecuri la +${i}"><small class="help">${it.fails?.[i]?'<br>Limită: '+it.fails[i]:''}</small>`:'<span class="help">Garantat</span>'}</td></tr>`).join('')}</tbody></table></div><p class="help">Costul include o reușită plus numărul de eșecuri pentru fiecare etapă activă. Limitele de eșec sunt cele din datele originale.</p></section><section class="panel"><div class="resetline"><h2>Materiale și prețuri</h2><button class="quiet" data-action="resetAdjust">Resetează cantitățile</button></div><p class="help">Cantitatea poate fi ajustată dacă ai deja materiale. Prețul este în Yang / bucată.</p><div id="materials"></div></section></div><section class="panel summary" id="upgradeSummary" aria-live="polite"></section></div>`;}
function materialRows(){const r=upgradeResult();$('materials').innerHTML=Object.keys(r.quantities).length?`<div class="tablewrap"><table><thead><tr><th>MATERIAL</th><th>CANTITATE</th><th>PREȚ UNITAR</th><th>COST</th></tr></thead><tbody>${Object.entries(r.quantities).map(([id,q])=>`<tr><td>${named(GAME.materials[id]||id)}</td><td><input type="number" min="0" step="1" data-qty="${id}" value="${q}" aria-label="Cantitate ${esc(GAME.materials[id])}"><br><small class="help">Necesar: ${fmt(r.required[id])}</small></td><td><input data-price="${id}" value="${state.prices[id]||''}" placeholder="0" aria-label="Preț ${esc(GAME.materials[id])}"><span class="errorhint" hidden></span></td><td id="subtotal-${id}">${short(q*(state.prices[id]||0))}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Nicio resursă pentru etapele selectate.</div>';paintUpgrade();}
function paintUpgrade(){const r=upgradeResult(),missing=Object.keys(r.quantities).filter(id=>r.quantities[id]>0&&!state.prices[id]).length;$('upgradeSummary').innerHTML=`<div class="eyebrow">BUGETUL PLANULUI</div><div class="divider"></div><div class="stat"><span>Materiale</span><b>${short(r.materials)}</b></div><div class="stat"><span>Taxe NPC</span><b>${short(r.fee)}</b></div><div class="divider"></div><small>TOTAL ESTIMAT</small><div class="total">${short(r.total)}</div><small>${fmt(r.total)} Yang</small>${missing?`<p class="help">${missing} materiale au preț zero sau necompletat. Totalul poate fi incomplet.</p>`:''}<div class="divider"></div><small>Prețurile sunt introduse de tine, nu sunt cotații live.</small>`;for(const [id,q]of Object.entries(r.quantities))if($('subtotal-'+id))$('subtotal-'+id).textContent=short(q*(state.prices[id]||0));}
function gaya(){const g=state.gaya;return heading('03 / RESURSE','Gaya, fără necunoscute.','Introdu prețurile materialelor și vezi costul complet, inclusiv taxa NPC.')+`<div class="layout"><div class="stack"><section class="panel"><h2>Prețurile materialelor</h2><div class="fields" style="grid-template-columns:1fr 1fr">${input('Glimmerstone · Yang / bucată','stone',g.stone||'')}${input('Glimmer Dust · Yang / bucată','dust',g.dust||'')}</div><p class="help">Sunt acceptate valori precum 250k și 1,5kk. Preț zero înseamnă că materialul nu este inclus în buget.</p></section><section class="panel"><h2>Cât Gaya vrei să produci?</h2>${input('Cantitate Gaya · 1–9.999','qty',g.qty,'type="number" min="1" max="9999" step="1"')}</section><section class="panel"><h2>Lista de materiale</h2><div id="gayaRecipe"></div></section></div><section class="panel summary" id="gayaSummary" aria-live="polite"></section></div>`;}
function paintGaya(){const g=state.gaya,r=Calc.gaya(g.qty,g.stone,g.dust);$('gayaRecipe').innerHTML=`<table><thead><tr><th>RESURSĂ</th><th>PENTRU 1 GAYA</th><th>PENTRU ${fmt(g.qty)} GAYA</th></tr></thead><tbody><tr><td>${named('Glimmerstone')}</td><td>1</td><td>${fmt(g.qty)}</td></tr><tr><td>${named('Glimmer Dust')}</td><td>10</td><td>${fmt(g.qty*10)}</td></tr><tr><td>Taxă NPC</td><td>250k Yang</td><td>${short(g.qty*250000)} Yang</td></tr></tbody></table>`;$('gayaSummary').innerHTML=`<div class="gayaart">${pic('Gaya')}</div><div class="eyebrow">COST DE PRODUCȚIE</div><div class="stat"><span>Materiale / Gaya</span><b>${short(r.materials)}</b></div><div class="stat"><span>NPC / Gaya</span><b>250k</b></div><div class="stat"><span>Cost / Gaya</span><b>${short(r.unit)}</b></div><div class="divider"></div><small>TOTAL PENTRU ${fmt(g.qty)} GAYA</small><div class="total">${short(r.total)}</div><small>${fmt(r.total)} Yang</small>${!g.stone||!g.dust?'<p class="help">Completează ambele prețuri pentru un buget complet.</p>':''}`;}
function selectedMetins(){return GAME.metins.filter(m=>state.metin.selected.includes(m.id))}
function metin(){const m=state.metin;return heading('02 / SIMULATOR','Unde merită să farmezi?','Aceeași sesiune, rezultate diferite. Compară maximum două tipuri de Metin.')+`<section class="panel"><div class="resetline"><h2>Personajul și sesiunea</h2><span class="tag">Salvare automată</span></div><div class="fields">${input('Daune / secundă · DPS','dps',m.dps)}${input('Durata sesiunii · minute','minutes',m.minutes)}${input('Deplasare între pietre · secunde','travel',m.travel)}</div><p class="help">DPS: 1–9.999.999 · Sesiune: 1–1.440 min · Deplasare: 0–600 sec. Timpul per piatră = HP / DPS + deplasare.</p><div class="pickgrid">${GAME.metins.map(x=>`<button class="pick ${m.selected.includes(x.id)?'selected':''}" data-metin="${x.id}" aria-pressed="${m.selected.includes(x.id)}"><b>${esc(x.name)}</b><small>${fmt(x.hp)} HP · ${(x.hp/m.dps).toFixed(1)} sec / distrugere</small></button>`).join('')}</div></section><div class="sectionline"><h2>Rezultatele sesiunii</h2><button class="primary" data-action="reroll" id="reroll">↻ Simulează din nou</button></div><p class="compare-note">Scenarii alternative pentru ${m.minutes} minute fiecare. Veniturile nu se adună.</p><div id="simStatus" class="status" role="status"></div><div id="simResults" class="results"></div><section class="panel" style="margin-top:22px"><div class="resetline"><h2>Prețuri de vânzare</h2><button class="quiet" data-action="resetMetin">Resetează prețurile</button></div><p class="help">Yang / bucată. Cupoanele se transformă automat în Yang; 10 fragmente formează un cristal sau o piatră.</p><div class="tablewrap"><table><thead><tr><th>MATERIAL</th><th>PREȚ UNITAR</th>${selectedMetins().map(x=>`<th>${esc(x.name)}</th>`).join('')}</tr></thead><tbody>${metinNames().map((n,i)=>`<tr><td>${named(n)}</td><td><input data-mprice="${i}" value="${m.prices[n]||''}" placeholder="0" aria-label="Preț ${esc(n)}"><span class="errorhint" hidden></span></td>${selectedMetins().map(x=>`<td data-value="${x.id}|${i}">—</td>`).join('')}</tr>`).join('')}</tbody></table></div></section><div class="notebox">Simulare aleatoare pe baza șanselor din arhivă; nu reprezintă un drop garantat sau date live. Media folosește conversia exactă a grupurilor de 10 fragmente. Intervalul P10–P90 este o aproximație normală și poate fi imprecis la puține dropuri rare. Nu sunt incluse alte costuri de farm.</div>`;}
function metinNames(){return [...new Set(selectedMetins().flatMap(m=>m.drops.filter(d=>!d[5]?.yang).map(d=>d[5]?.to||d[0])))];}
let worker;try{worker=new Worker('worker.js');worker.onmessage=({data})=>{if(data.id!==job)return;runs=data.runs;if(page==='metin'){paintMetin();$('simStatus').textContent='Simulare finalizată. Schimbarea prețurilor păstrează același rezultat.';$('reroll').disabled=false;}};worker.onerror=()=>{if(page==='metin'){$('simStatus').textContent='Simularea nu a putut porni. Reîncarcă pagina din versiunea web.';$('reroll').disabled=false;}}}catch{}
function simulate(){if(!worker){$('simStatus').textContent='Simulatorul necesită deschiderea printr-un server web. Vezi README.';return;}job++;$('simStatus').textContent='Se calculează dropurile…';$('reroll').disabled=true;$('simResults').innerHTML='';worker.postMessage({id:job,metins:selectedMetins(),...state.metin});}
function paintMetin(){if(page!=='metin')return;const s=state.metin;
 $('simResults').innerHTML=selectedMetins().map(m=>{const r=runs[m.id];if(!r)return '';let value=r.coupons;for(const[n,q]of Object.entries(r.items))value+=q*(s.prices[n]||0);const e=Calc.expected(m,r.kills,s.prices);return `<section class="panel"><h2>${esc(m.name)}</h2><div class="resulttop"><div><small class="help">VENIT SIMULAT</small><div class="big">${short(value)}</div><small class="help">${fmt(value)} Yang</small></div><div><small class="help">PIETRE DISTRUSE</small><div class="big">${fmt(r.kills)}</div></div></div><div class="stat"><span>Cupoane Yang</span><b>${short(r.coupons)}</b></div><div class="stat"><span>Materiale evaluate</span><b>${short(value-r.coupons)}</b></div><div class="stat"><span>Venit / oră</span><b>${short(value*60/s.minutes)}</b></div><div class="divider"></div><p class="help">Medie calculată: <b>${short(e.mean)}</b><br>P10–P90 aproximativ: ${short(e.low)} – ${short(e.high)}</p><details><summary>Dropuri și conversii</summary><div class="tablewrap"><table><thead><tr><th>DROP</th><th>ȘANSĂ</th><th>CANTITATE</th><th>CONVERSIE</th></tr></thead><tbody>${m.drops.map(([n,ch,lo,hi,t,c])=>`<tr><td>${esc(n)}<br><small class="help">${lo}–${hi} / drop</small></td><td>${ch}%</td><td>${fmt(r.counts[n])}</td><td>${c?.yang?short(r.counts[n]*c.yang)+' Yang':c?.to?`${Math.floor(r.counts[n]/10)} × ${esc(c.to)}<br><small class="help">${r.counts[n]%10} fragmente rămase</small>`:'—'}</td></tr>`).join('')}</tbody></table></div></details></section>`}).join('');
 document.querySelectorAll('[data-value]').forEach(el=>{const[id,index]=el.dataset.value.split('|'),n=metinNames()[+index],q=runs[id]?.items[n]||0;el.textContent=`${fmt(q)} × = ${short(q*(s.prices[n]||0))}`});
}
function render(){page=location.hash.slice(1);if(!['home','upgrade','gaya','metin'].includes(page))page='home';$('crumb').textContent={home:'Prezentare',upgrade:'Cost upgrade',metin:'Simulator Metin',gaya:'Calculator Gaya'}[page];document.querySelectorAll('nav a').forEach(a=>{a.classList.toggle('active',a.dataset.page===page);if(a.dataset.page===page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});$('main').innerHTML=({home,upgrade,metin,gaya})[page]();if(page==='upgrade')materialRows();if(page==='gaya')paintGaya();if(page==='metin')simulate();}
function validate(el,n,min=0,max=1e12,integer=false){const ok=n!==null&&Number.isFinite(n)&&n>=min&&n<=max&&(!integer||Number.isInteger(n));el.setAttribute('aria-invalid',String(!ok));el.setCustomValidity(ok?'':'Valoare invalidă');const hint=el.parentElement.querySelector('.errorhint');if(hint){hint.hidden=ok;hint.textContent=`Introdu ${integer?'un număr întreg':'o valoare'} între ${fmt(min)} și ${fmt(max)}.`;}return ok;}
document.addEventListener('input',e=>{const el=e.target,d=el.dataset;let n=Calc.amount(el.value);
 if(d.price!==undefined){if(!validate(el,n))return;state.prices[d.price]=n;paintUpgrade();}
 else if(d.mprice!==undefined){if(!validate(el,n))return;state.metin.prices[metinNames()[+d.mprice]]=n;paintMetin();}
 else if(d.key){if(page==='gaya'){if(!validate(el,n,d.key==='qty'?1:0,d.key==='qty'?9999:1e12,d.key==='qty'))return;state.gaya[d.key]=n;paintGaya();}else{const ranges={dps:[1,9999999],minutes:[1,1440],travel:[0,600]};if(!validate(el,n,...ranges[d.key],true))return;state.metin[d.key]=n;clearTimeout(simulate.timer);simulate.timer=setTimeout(()=>{if(page==='metin'){document.querySelector('.compare-note').textContent=`Scenarii alternative pentru ${state.metin.minutes} minute fiecare. Veniturile nu se adună.`;document.querySelectorAll('[data-metin]').forEach(b=>{const m=GAME.metins.find(m=>m.id===b.dataset.metin);b.querySelector('small').textContent=`${fmt(m.hp)} HP · ${(m.hp/state.metin.dps).toFixed(1)} sec / distrugere`;});simulate();}},200);}}
 else if(d.fail!==undefined){if(!validate(el,n,0,current().fails?.[d.fail]||99,true))return;state.fails[state.item+'|'+d.fail]=n;materialRows();}
 else if(d.qty!==undefined){if(!validate(el,n,0,1e12,true))return;state.adjust[state.item+'|'+d.qty]=n-(upgradeResult().required[d.qty]||0);paintUpgrade();}
 else return;save();
});
document.addEventListener('change',async e=>{const el=e.target;if(el.id==='item'){state.item=el.value;save();render();}if(el.dataset.step!==undefined){state.enabled[state.item+'|'+el.dataset.step]=el.checked;el.closest('tr').classList.toggle('off',!el.checked);save();materialRows();}if(el.id==='import'&&el.files[0]){try{if(el.files[0].size>1000000)throw Error();const parsed=JSON.parse(await el.files[0].text());if(parsed.format!=='lirin-forge-v1')throw Error();state=restore(parsed.state);save();render();toast('Setările au fost importate.')}catch{toast('Fișier invalid. Alege un export Lirin Forge.')}}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.go){location.hash=b.dataset.go;return;}if(b.id==='export'){const blob=new Blob([JSON.stringify({format:'lirin-forge-v1',state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='lirin-forge-settings.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}if(b.dataset.cat!==undefined){state.item=GAME.items.find(x=>x.c===+b.dataset.cat).n;save();render();return;}if(b.dataset.metin){const ids=state.metin.selected,id=b.dataset.metin,i=ids.indexOf(id);if(i>=0){if(ids.length===1){toast('Păstrează cel puțin un Metin selectat.');return;}ids.splice(i,1);}else{if(ids.length===2)ids.shift();ids.push(id);}save();render();return;}
 switch(b.dataset.action){case 'all':{const it=current(),all=it.steps.every((r,i)=>!r||state.enabled[it.n+'|'+i]!==false);it.steps.forEach((r,i)=>{if(r)state.enabled[it.n+'|'+i]=!all});save();render();break;}case 'resetUpgrade':for(const key of ['enabled','fails','adjust'])for(const k of Object.keys(state[key]))if(k.startsWith(state.item+'|'))delete state[key][k];save();render();break;case 'resetAdjust':for(const k of Object.keys(state.adjust))if(k.startsWith(state.item+'|'))delete state.adjust[k];save();materialRows();break;case 'reroll':state.metin.seed=crypto.getRandomValues(new Uint32Array(1))[0];save();simulate();break;case 'resetMetin':for(const n of metinNames())delete state.metin.prices[n];save();render();break;}
});
document.addEventListener('error',e=>{if(e.target.tagName==='IMG')e.target.hidden=true},true);
addEventListener('hashchange',render);render();
